/* Generated by `helix system machines` from machine.ts beside it. Do not
   edit: change the machine and run it again. */
import { type NestedContext, type NestedInput, forgotten, turn, wraps } from './machine.js'

export type { NestedContext, NestedInput } from './machine.js'

/** The name machine.ts exports the machine as. */
export const NAME = 'nested'

/** The state `closed`. */
export const STATE_CLOSED = 0
/** The state `first`. */
export const STATE_FIRST = 1
/** The state `second`. */
export const STATE_SECOND = 2
/** Each state's name, by its number. */
export const STATES = ['closed', 'first', 'second'] as const

/** Each state as the machine writes it, by the number a deadline names its owner by. */
export const NODES = ['closed', 'open', 'first', 'second'] as const

/** The event `OPEN`. */
export const EVENT_OPEN = 0
/** The event `NEXT`. */
export const EVENT_NEXT = 1
/** The event `CLOSE`. */
export const EVENT_CLOSE = 2
/** Each event's name, by its number. */
export const EVENTS = ['OPEN', 'NEXT', 'CLOSE'] as const

/** The effect `focus`. */
export const EFFECT_FOCUS = 0
/** The effect `hide`. */
export const EFFECT_HIDE = 1
/** The effect `reset`. */
export const EFFECT_RESET = 2
/** The effect `show`. */
export const EFFECT_SHOW = 3
/** The effect `deadline`. */
export const EFFECT_DEADLINE = 4
/** The effect `deadline-end`. */
export const EFFECT_DEADLINE_END = 5
/** Each effect's name, by its number. */
export const EFFECTS = ['focus', 'hide', 'reset', 'show', 'deadline', 'deadline-end'] as const

/** Each request event's name, by its number. */
export const ASKS = [] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: NestedContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (_context: NestedContext): number =>
  STATE_CLOSED

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (state: number): readonly Effect[] => {
  switch (state) {
    case STATE_FIRST:
      return [[EFFECT_SHOW], [EFFECT_DEADLINE, { ms: 3000, owner: 1 }], [EFFECT_FOCUS]]
    case STATE_SECOND:
      return [[EFFECT_SHOW], [EFFECT_DEADLINE, { ms: 3000, owner: 1 }]]
  }
  return []
}

/** What `closed` does with each event. */
const inClosed = (context: NestedContext, event: number, _input: NestedInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_OPEN:
      return { context: context, effects: [[EFFECT_SHOW], [EFFECT_DEADLINE, { ms: 3000, owner: 1 }], [EFFECT_FOCUS]], state: STATE_FIRST }
  }
  return undefined
}

/** What `first` does with each event. */
const inFirst = (context: NestedContext, event: number, _input: NestedInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_NEXT:
      return { context: turn(context), effects: [], state: STATE_SECOND }
    case EVENT_CLOSE:
      return { context: context, effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_HIDE]], state: STATE_CLOSED }
  }
  return undefined
}

/** What `second` does with each event. */
const inSecond = (context: NestedContext, event: number, input: NestedInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_OPEN:
      return { context: context, effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_HIDE], [EFFECT_SHOW], [EFFECT_DEADLINE, { ms: 3000, owner: 1 }], [EFFECT_FOCUS]], state: STATE_FIRST }
    case EVENT_NEXT:
      return wraps(context, input) ? { context: turn(context), effects: [[EFFECT_FOCUS]], state: STATE_FIRST } : undefined
    case EVENT_CLOSE:
      return { context: context, effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_HIDE]], state: STATE_CLOSED }
  }
  return undefined
}

/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: NestedContext, event: number, input: NestedInput): Move | Asking | undefined => {
  switch (state) {
    case STATE_CLOSED:
      return inClosed(context, event, input)
    case STATE_FIRST:
      return inFirst(context, event, input)
    case STATE_SECOND:
      return inSecond(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (state: number, context: NestedContext, owner: number): Move | undefined => {
  switch (state) {
    case STATE_FIRST:
      return owner === 1 ? { context: forgotten(context), effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_HIDE]], state: STATE_CLOSED } : undefined
    case STATE_SECOND:
      return owner === 1 ? { context: forgotten(context), effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_HIDE]], state: STATE_CLOSED } : undefined
  }
  return undefined
}

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (state: number, context: NestedContext): Move | undefined => {
  switch (state) {
    case STATE_CLOSED:
      return { context: forgotten(context), effects: [[EFFECT_RESET]], state: STATE_CLOSED }
    case STATE_FIRST:
      return { context: forgotten(context), effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_HIDE], [EFFECT_RESET]], state: STATE_CLOSED }
    case STATE_SECOND:
      return { context: forgotten(context), effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_HIDE], [EFFECT_RESET]], state: STATE_CLOSED }
  }
  return undefined
}

/** The custom states a host records while the machine is in `state`. */
export const mark = (state: number): readonly string[] => {
  switch (state) {
    case STATE_FIRST:
      return ['open']
    case STATE_SECOND:
      return ['open', 'second']
  }
  return []
}
